// リコンサイラ。台帳の desired と state の差分を計算し、実サービスへ適用する。
// 追加・役割変更・チーム異動・削除は、すべてこの1つのループの現れ。
// 起動は (1) 台帳のマージ Webhook (2) 日次スケジュール の2系統を想定。
// 設計: docs/design/01-member-lifecycle.md

return [{ json: { kind: 'catalog', __dryRun: $input.first()?.json?.dryRun === true } }];

// あるべき grant 集合 = 役割マトリクス ∪ ⋃チームマトリクス ∪ extra_grants
// これと state の付与実態を比べ、実行すべき操作を決める。
// status: left のメンバーは「あるべき grant = 空」なので、差分が全剥奪になる。
//
// 出力は常に「type: connector」か「type: none」のアイテム。
// 手動サービスのタスク仕様と既存タスクは __plan に載せ、後段でまとめて state に書く。

const crypto = require('crypto');

// dryRun: 何も適用せず、何が起きるかだけを返す(監査と事前確認に使う)。
// 設計: docs/design/08-safeguards.md#リコンサイラの安全装置
const dryRun = $('カタログ読み取りの入力').first().json.__dryRun === true;

const catalog = {};
for (const it of $('カタログを読む').all()) catalog[it.json.id] = it.json.desired;

const services = catalog.services?.services ?? [];
const roles = catalog['role-matrix']?.roles ?? {};
const teams = catalog['team-matrix']?.teams ?? {};

// カタログの connector 名 → n8n のワークフロー ID。
// 未対応のコネクタは実行せず skipped として可視化する(黙って無視しない)。
const CONNECTORS = { 'service-keycloak': 'svckeycloak00001' };

const members = $input.all().map((i) => i.json).filter((m) => m.desired);

const actions = [];
const skipped = [];
const manualTasks = [];
const existingTasks = {};
let revocationCount = 0;

const webhookBase = String($env.WEBHOOK_URL ?? 'http://localhost:5678/').replace(/\/$/, '');
const today = new Date();
const isoDate = (d) => d.toISOString().slice(0, 10);

for (const m of members) {
  const d = m.desired;
  const state = m.state ?? {};
  const isLeft = d.status === 'left';
  existingTasks[m.id] = Array.isArray(state.tasks) ? state.tasks : [];

  for (const svc of services) {
    if (svc.enabled === false) continue;

    const desired = [];
    if (!isLeft) {
      const fromRole = roles[d.role]?.[svc.service_id];
      if (fromRole) desired.push(fromRole);
      for (const t of (d.teams ?? [])) {
        const cell = teams[t]?.[svc.service_id];
        const v = (cell && typeof cell === 'object' && !Array.isArray(cell)) ? cell[d.role] : cell;
        if (v) desired.push(v);
      }
      for (const eg of (d.extra_grants ?? [])) {
        if (eg.service === svc.service_id && eg.grant) desired.push(eg.grant);
      }
    }
    const want = [...new Set(desired)].sort();
    const have = [...new Set(state.grants?.[svc.service_id] ?? [])].sort();
    if (JSON.stringify(want) === JSON.stringify(have)) continue; // 収束済み

    revocationCount += have.filter((g) => !want.includes(g)).length;

    const operation = isLeft ? 'remove' : (have.length > 0 ? 'change' : 'add');
    const spec = svc.operations?.[operation];
    if (!spec) continue;

    const entry = {
      memberId: m.id,
      serviceId: svc.service_id,
      operation,
      member: { id: m.id, email: d.email, name: d.name },
      desired: want,
      current: have,
    };

    if (spec.execute === 'api' && CONNECTORS[spec.connector]) {
      actions.push({ ...entry, connectorWorkflowId: CONNECTORS[spec.connector] });
      continue;
    }
    if (spec.execute === 'api') {
      skipped.push({ ...entry, reason: `コネクタ ${spec.connector} は未実装` });
      continue;
    }

    // 人手が必要な操作はタスクとして起票する。
    // id を (サービス:操作) で決めるため、日次で再実行しても重複しない。
    const taskId = `${svc.service_id}:${operation}`;
    const tpl = spec.task_template ?? {};
    const due = new Date(today);
    due.setDate(due.getDate() + Number(tpl.due_days ?? 7));

    const render = (s) => String(s ?? '')
      .replaceAll('{member}', d.name ?? m.id)
      .replaceAll('{grant}', (want.length ? want : have).join(', '));

    manualTasks.push({
      memberId: m.id,
      task: {
        id: taskId,
        kind: `member-${operation}`,
        service: svc.service_id,
        operation,
        subject: render(tpl.subject) || `${d.name ?? m.id}: ${svc.name ?? svc.service_id} の ${operation}`,
        steps: render(tpl.steps),
        assignee: $env[tpl.assignee] || tpl.assignee || $env.ADMIN_EMAILS,
        due: isoDate(due),
        status: 'open',
        verify: spec.verify ?? 'human',
        blocking: spec.blocking !== false,
        grants: want,          // 完了時に state.grants へ反映する値
        remind_count: 0,
        last_reminded_at: null,
        token: crypto.randomBytes(16).toString('hex'),
        created_at: new Date().toISOString(),
      },
      webhookBase,
    });
  }
}

// サーキットブレーカー: 一度に大量の剥奪が出たら止めて人の確認を求める。
// マトリクスの編集ミスや差分計算の不具合で全員が一斉剥奪されるのを防ぐ。
const limit = Number($env.REVOKE_CIRCUIT_BREAKER ?? 5);
if (revocationCount > limit) {
  throw new Error(`reconcile: 剥奪が ${revocationCount} 件で上限 ${limit} を超えました。カタログの変更ミスの可能性があるため停止します(意図した一括処理なら REVOKE_CIRCUIT_BREAKER を一時的に上げてください)`);
}

const plan = { skipped, manualTasks, existingTasks, revocationCount, dryRun, actions };

// ドライランでは適用側に一切流さない
if (dryRun || actions.length === 0) {
  return [{ json: { type: 'none', __plan: plan } }];
}
return actions.map((json) => ({ json: { type: 'connector', ...json, __plan: plan } }));

// コネクタの結果と手動タスクを、メンバーごとの state patch にまとめる。
// 成功なら grants を更新し、失敗は記録して次の日次リコンサイルに委ねる
// (desired ≠ state が残るので自動的に再試行される)。

const planItems = $('差分を計算する').all().map((i) => i.json);
const meta = planItems[0]?.__plan ?? {};
const connectorPlan = planItems.filter((p) => p.type === 'connector');
const results = $input.all().map((i) => i.json);
const hasConnectorResults = !results.some((r) => r?.__noConnector);

const acc = new Map();
const get = (id) => {
  if (!acc.has(id)) acc.set(id, { grants: {}, failures: {}, applied: [], tasks: null });
  return acc.get(id);
};

if (hasConnectorResults) {
  connectorPlan.forEach((p, i) => {
    const r = results[i] ?? {};
    const a = get(p.memberId);
    if (r.ok === true) {
      a.grants[p.serviceId] = p.desired;
      a.applied.push(`${p.serviceId}:${p.operation}`);
      a.failures[p.serviceId] = null;   // 解消した失敗記録を消す(null = キー削除)
    } else {
      a.failures[p.serviceId] = String(r.detail ?? r.error?.message ?? 'コネクタが失敗しました').slice(0, 200);
    }
  });
}

// 手動タスクを起票する。同じ id の open なタスクがあれば作り直さない(日次実行で重複しない)。
for (const mt of (meta.manualTasks ?? [])) {
  const a = get(mt.memberId);
  const existing = a.tasks ?? [...(meta.existingTasks?.[mt.memberId] ?? [])];
  const already = existing.find((t) => t.id === mt.task.id && t.status === 'open');
  if (!already) {
    a.tasksChanged = true;
    const url = `${mt.webhookBase}/webhook/task-complete`
      + `?member=${encodeURIComponent(mt.memberId)}`
      + `&task=${encodeURIComponent(mt.task.id)}`
      + `&token=${mt.task.token}`;
    existing.push({ ...mt.task, complete_url: url });
    a.applied.push(`task:${mt.task.id}`);
  }
  a.tasks = existing;
}

const now = new Date().toISOString();
const patches = [...acc.entries()]
  // 実質的な変更が無いメンバーは書き込まない(毎回コミットが増えるのを防ぐ)
  .filter(([, a]) => Object.keys(a.grants).length || a.tasksChanged
    || Object.values(a.failures).some((v) => v !== null))
  .map(([memberId, a]) => ({ json: {
  kind: 'members',
  id: memberId,
  patch: {
    ...(Object.keys(a.grants).length ? { grants: a.grants } : {}),
    ...(a.tasksChanged ? { tasks: a.tasks } : {}),
    failures: Object.values(a.failures).some((v) => v !== null) ? a.failures : null,
    updated_at: now,
  },
  reason: a.applied.length ? a.applied.join(', ') : '適用結果を記録',
}}));

// 書き込むものが無くてもサマリを返せるよう、マーカーを1件流す
return patches.length ? patches : [{ json: { __nowrite: true } }];

// 実行サマリ。成功・失敗・起票したタスクを区別して返す。
const planItems = $('差分を計算する').all().map((i) => i.json);
const meta = planItems[0]?.__plan ?? {};
const connectorPlan = planItems.filter((p) => p.type === 'connector');
// コネクタを実行しない経路もあるため、未実行なら空として扱う
let results = [];
try { results = $('コネクタを実行').all().map((i) => i.json); } catch (e) { results = []; }
const writes = $input.all().map((i) => i.json).filter((w) => w && !w.__nowrite);

const applied = [];
const failed = [];
connectorPlan.forEach((p, i) => {
  const label = `${p.memberId}/${p.serviceId}:${p.operation}`;
  if (results[i]?.ok === true) applied.push(label);
  else failed.push(`${label} — ${String(results[i]?.detail ?? results[i]?.error?.message ?? '失敗').slice(0, 120)}`);
});

// ドライランでは「これから起きること」を返す(適用はしていない)
if (meta.dryRun) {
  return [{ json: {
    dry_run: true,
    pending: (meta.actions ?? []).map((a) => `${a.memberId}/${a.serviceId}:${a.operation}`
      + ` 付与[${a.desired.filter((g) => !a.current.includes(g)).join(', ') || '—'}]`
      + ` 剥奪[${a.current.filter((g) => !a.desired.includes(g)).join(', ') || '—'}]`),
    pending_tasks: (meta.manualTasks ?? [])
      .filter((t) => !(meta.existingTasks?.[t.memberId] ?? []).some((e) => e.id === t.task.id && e.status === 'open'))
      .map((t) => `${t.memberId}/${t.task.id}`),
    skipped: (meta.skipped ?? []).map((x) => `${x.memberId}/${x.serviceId}: ${x.reason}`),
    revocations: meta.revocationCount ?? 0,
  }}];
}

return [{ json: {
  applied,
  failed,
  // 新規に起票したものだけを載せる(既に open なタスクは再掲しない)
  tasks: (meta.manualTasks ?? [])
    .filter((t) => !(meta.existingTasks?.[t.memberId] ?? []).some((e) => e.id === t.task.id && e.status === 'open'))
    .map((t) => `${t.memberId}/${t.task.id} (期限 ${t.task.due}, 担当 ${t.task.assignee})`),
  written: writes.filter((w) => w.ok).map((w) => w.path),
  skipped: (meta.skipped ?? []).map((s) => `${s.memberId}/${s.serviceId}: ${s.reason}`),
  revocations: meta.revocationCount ?? 0,
}}];
